import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Simplest case ---
  it("should charge only the processing fee for an empty item list — premium 5 G", () => {
    const output = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    });

    expect(output).toEqual({ results: [{ premium: 5 }] });
  });

  // --- Item base premiums (each + 5 G fee + 10 G first insurance) ---
  // Base premium 100 G; end-to-end for a 0-year customer this is
  // 100 base + 10 first-insurance surcharge + 5 processing fee = 115 G.
  it("should quote a plain sword — base premium 100 G", () => {
    const output = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        { op: "quote", items: [{ type: "sword", material: "steel", enchantment: 3, cursed: false }] },
      ],
    });

    expect(output).toEqual({ results: [{ premium: 115 }] });
  });
  // Base premium 60 G; end-to-end for a 0-year customer this is
  // 60 base + 6 first-insurance surcharge + 5 processing fee = 71 G.
  it("should quote a plain amulet — base premium 60 G", () => {
    const output = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        { op: "quote", items: [{ type: "amulet", material: "silver", enchantment: 2, cursed: false }] },
      ],
    });

    expect(output).toEqual({ results: [{ premium: 71 }] });
  });
  // Base premium 80 G; end-to-end for a 0-year customer this is
  // 80 base + 8 first-insurance surcharge + 5 processing fee = 93 G.
  it("should quote a plain staff — base premium 80 G", () => {
    const output = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        { op: "quote", items: [{ type: "staff", material: "oak", enchantment: 1, cursed: false }] },
      ],
    });

    expect(output).toEqual({ results: [{ premium: 93 }] });
  });
  // Base premium 40 G; end-to-end for a 0-year customer this is
  // 40 base + 4 first-insurance surcharge + 5 processing fee = 49 G.
  it("should quote a plain potion — base premium 40 G", () => {
    const output = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        { op: "quote", items: [{ type: "potion", material: "glass", enchantment: 0, cursed: false }] },
      ],
    });

    expect(output).toEqual({ results: [{ premium: 49 }] });
  });
  // Components are insured at 250 G with a 25 G base premium each.
  // End-to-end for a 0-year customer: 25 base + 2.5 first-insurance
  // surcharge + 5 fee = 32.5, rounded UP in the MHPCO's favour = 33 G.
  it("should quote a single rune component — base premium 25 G", () => {
    const output = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }] }],
    });

    expect(output).toEqual({ results: [{ premium: 33 }] });
  });
  it.todo("should quote a single moonstone component — base premium 25 G");

  // --- Building block of 3 alike components ---
  it.todo("should quote 2 runes — base premium 50 G (no block)");
  it.todo("should quote 3 runes — base premium 60 G (block applies)");
  it.todo("should quote 4 runes — base premium 100 G (no block — block requires exactly 3)");
  it.todo("should quote 7 runes — base premium 175 G");

  // --- "Alike" components: same type, not same family ---
  it.todo("should quote 2 runes + 1 moonstone — base premium 75 G (no block: different types)");
  it.todo("should quote 3 runes + 3 moonstones — base premium 120 G (two separate blocks)");

  // --- Premium modifiers in isolation ---
  it.todo("should add 50 % curse surcharge — cursed sword base premium 100 G → 150 G");
  it.todo("should add 30 % high-enchantment surcharge for enchantment 5 — sword 100 G → 130 G");
  it.todo("should not add high-enchantment surcharge for enchantment 4 — sword stays 100 G");
  it.todo("should apply both surcharges to a cursed sword with enchantment 5 — 100 G → 180 G");
  it.todo("should apply 20 % loyalty discount for exactly 2 years with MHPCO");
  it.todo("should not apply loyalty discount for 1 year with MHPCO");
  it.todo("should add 10 % initial assessment surcharge for a first insurance");
  it.todo("should apply 15 % discount on each contract after the first");

  // --- Modifier scope on multi-item policies ---
  it.todo("should apply curse surcharge to the cursed item only — cursed sword + plain amulet → 210 G before fee");
  it.todo("should apply policy-wide modifiers to the policy base premium and add the fee last");

  // --- Rounding in the MHPCO's favor ---
  it.todo("should round a premium of 197.5 G up to 198 G");
  it.todo("should round a payout of 350.5 G down to 350 G");

  // --- Integration examples ---
  it.todo("should quote a newcomer's cursed sword (0 years, enchantment 3) — premium 165 G");
  it.todo("should quote a long-standing customer's second contract (3 years, cursed sword enchantment 7) — premium 160 G");

  // --- Insurance sum and cap ---
  it.todo("should compute insurance sum 2000 G and cap 4000 G for a policy covering two swords");
  it.todo("should compute insurance sum 1600 G and cap 3200 G for a policy covering a sword and an amulet");
  it.todo("should compute cap 2000 G for a cursed sword — premium modifiers do not raise the cap (premium 165 G)");
  it.todo("should compute insurance sum 1750 G for a sword and 3 runes — block discount affects the premium only");

  // --- Claim processing: standard reimbursement ---
  it.todo("should pay out 400 G for a regular sword (steel, enchantment 3) with damage 500 G");
  it.todo("should pay out 100 G for a damaged rune (damage 200 G) — no special clause applies");

  // --- Claim processing: special clauses ---
  it.todo("should pay out 400 G for a dragon-material sword with exactly enchantment 8 and damage 1000 G");
  it.todo("should pay out 400 G for a dragon-material sword with enchantment 9 and damage 1000 G (50 % rule wins)");
  it.todo("should pay out 700 G for a dragon-material sword with enchantment 5 and damage 800 G");
  it.todo("should pay out 400 G for a steel sword with enchantment 9 and damage 1000 G");

  // --- Deductible per damage event ---
  it.todo("should apply the 100 G deductible once per damaged item — sword 500 G + amulet 300 G → payout 600 G");
  it.todo("should treat two sword damage entries as separate damages, each with its own deductible");

  // --- Cap exhaustion across successive claims ---
  it.todo("should pay out 1400 G and leave cap remaining 600 G for a first claim of 1500 G on a sword policy");
  it.todo("should pay out 600 G and leave cap remaining 0 G for a second claim of 1500 G on the same policy");

  // --- Error cases (CLI exits non-zero) ---
  it.todo("should reject a quote containing an item with an unknown type (e.g. broomstick)");
  it.todo("should reject a claim whose damaged item is not part of the policy (amulet damaged, only a sword insured)");
  it.todo("should reject a claim with a damage entry of an unknown item type");
  it.todo("should reject a claim with a negative damage amount (amount: -200)");
  it.todo("should reject a claim with more damage entries of a type than the policy covers (two sword damages, one sword insured)");

  // --- CLI end-to-end ---
  it.todo("should process the schema example scenario and write a results array matching the steps order");
  it.todo("should exit non-zero and write an error description to stderr for an invalid scenario, with no results on stdout");
});

