export const runScenario = (scenario: Scenario): ScenarioOutput => {
  // Claim steps reference a policy by the index of the quote step that created
  // it, and the remaining cap persists across claims — so the steps cannot be
  // processed independently of one another.
  const remainingCaps = new Map<number, number>();
  const results: StepResult[] = [];

  scenario.steps.forEach((step, stepIndex) => {
    if (step.op === "quote") {
      remainingCaps.set(stepIndex, policyCap(step.items));
      results.push({
        premium: roundPremium(
          quotePremium(step, scenario.customer, stepIndex),
        ),
      });
      return;
    }

    const remainingCap = remainingCaps.get(step.policy) ?? 0;
    const payout = claimPayout(step.incident, remainingCap);
    remainingCaps.set(step.policy, remainingCap - payout);
    results.push({ payout, remainingCap: remainingCap - payout });
  });

  return { results };
};

