input.new_string:
/**
 * Damage to a very highly enchanted item is only half reimbursed. NOTE this
 * threshold (8) is NOT the quote-side `HIGH_ENCHANTMENT_THRESHOLD` (5) — two
 * distinct rules that both key off enchantment.
 */
const HIGH_ENCHANTMENT_REIMBURSEMENT_THRESHOLD = 8;
const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;

/** The share of a damage amount the MHPCO reimburses, before the deductible. */
const reimbursementRate = (item: Item | undefined): number =>
  (item?.enchantment ?? 0) >= HIGH_ENCHANTMENT_REIMBURSEMENT_THRESHOLD
    ? HIGH_ENCHANTMENT_REIMBURSEMENT_RATE
    : 1;

const claimPayout = (
  incident: Incident,
  insuredItems: Item[],
  remainingCap: number,
): number => {
  // Reimburse first, deduct second: a 1000 G damage at 50 % is 500 − 100 = 400,
  // not (1000 − 100) / 2 = 450.
  const reimbursed = incident.damages.reduce((sum, damage) => {
    const item = insuredItems.find((candidate) => candidate.type === damage.itemType);
    return (
      sum + damage.amount * reimbursementRate(item) - DEDUCTIBLE_PER_DAMAGE
    );
  }, 0);
  return Math.min(reimbursed, remainingCap);
};

